const map = await (await fetch('/debug/dist/app.min.js.map')).json();
const B64='ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/';
function decodeVLQ(str){
  const result=[]; let shift=0, value=0;
  for (const c of str){
    const digit = B64.indexOf(c);
    const cont = digit & 32;
    const val = digit & 31;
    value += val << shift;
    if (cont) { shift += 5; }
    else { const neg = value & 1; value >>>=1; result.push(neg? -value : value); shift=0; value=0; }
  }
  return result;
}
const lines = map.mappings.split(';');
const segs=[];
let genLine=0, genCol=0, srcIdx=0, srcLine=0, srcCol=0;
for (const line of lines){
  genCol=0;
  if(line.length){
    for(const seg of line.split(',')){
      const d = decodeVLQ(seg);
      genCol += d[0];
      if(d.length>1){ srcIdx+=d[1]; srcLine+=d[2]; srcCol+=d[3]; }
      segs.push({genLine, genCol, srcLine, srcCol});
    }
  }
  genLine++;
}
JSON.stringify(segs.filter(s=>s.genLine===0 && s.genCol>=100 && s.genCol<=240));

